package io.knowledgebrain.space;
import java.time.*;import java.util.List;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class IntegrationAuthorizationTest {
 MockHttpServletRequest request(){var r=new MockHttpServletRequest();r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));return r;}
 @Test void onlyRegisteredOwnerOfPrivatePersonalSpaceCanUseGitHub(){var spaces=mock(PersonalSpaceStore.class);var identity=mock(IdentityPrincipalClient.class);var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();var api=new IntegrationAuthorizationController(spaces,identity,"a".repeat(43));for(String action:new String[]{"GITHUB_READ","GITHUB_WRITE"}){when(identity.resolve("b".repeat(43),null)).thenReturn(new IdentityPrincipalClient.Principal(actor,"REGISTERED",Instant.now().plusSeconds(60)));when(spaces.visible(space,actor)).thenReturn(new PersonalSpaceStore.SpaceView(space,"PERSONAL","PRIVATE","OWNER"));assertEquals(actor,api.authorize(new IntegrationAuthorizationController.Check(space,"b".repeat(43),action),request()).getBody().principalId());for(String role:List.of("VIEWER","EDITOR","ADMIN")){when(spaces.visible(space,actor)).thenReturn(new PersonalSpaceStore.SpaceView(space,"PERSONAL","PRIVATE",role));assertThrows(ResponseStatusException.class,()->api.authorize(new IntegrationAuthorizationController.Check(space,"b".repeat(43),action),request()));}when(identity.resolve("b".repeat(43),null)).thenReturn(new IdentityPrincipalClient.Principal(actor,"GUEST",Instant.now().plusSeconds(60)));assertEquals(403,assertThrows(ResponseStatusException.class,()->api.authorize(new IntegrationAuthorizationController.Check(space,"b".repeat(43),action),request())).getStatusCode().value());}when(identity.resolve("b".repeat(43),null)).thenReturn(new IdentityPrincipalClient.Principal(actor,"REGISTERED",Instant.now().plusSeconds(60)));when(spaces.visible(space,actor)).thenReturn(null);assertEquals(404,assertThrows(ResponseStatusException.class,()->api.authorize(new IntegrationAuthorizationController.Check(space,"b".repeat(43),"GITHUB_READ"),request())).getStatusCode().value());}
 @Test void internalCapabilityNeverAcceptsBrowserCookiesOrOtherDomainActions(){var spaces=mock(PersonalSpaceStore.class);var identity=mock(IdentityPrincipalClient.class);var api=new IntegrationAuthorizationController(spaces,identity,"a".repeat(43));var id=new UuidV7(Clock.systemUTC()).next();var cookie=request();cookie.addHeader("Cookie","__Host-brain_guest=anything");assertThrows(ResponseStatusException.class,()->api.authorize(new IntegrationAuthorizationController.Check(id,"b".repeat(43),"GITHUB_READ"),cookie));for(String action:new String[]{"CONCEPT_WRITE","NOTE_READ","GOAL_READ","BRAIN_SEARCH"})assertThrows(ResponseStatusException.class,()->api.authorize(new IntegrationAuthorizationController.Check(id,"b".repeat(43),action),request()));verifyNoInteractions(spaces,identity);}
}
